// SIMULATOR SENSOR RUANG 2 - KELOMPOK 7

// Generate suhu antara 24-32 derajat Celsius
let temperature = Number((24 + Math.random() * 8).toFixed(1));

// Generate kelembapan antara 50-80 persen
let humidity = Math.floor(50 + Math.random() * 31);

// Pesan suhu
let msgTemperature = {
    topic: "pens/klp7/ruang2/temperature",
    payload: temperature
};

// Pesan kelembapan
let msgHumidity = {
    topic: "pens/klp7/ruang2/humidity",
    payload: humidity
};

// Kirim dua pesan melalui satu output
return [[msgTemperature, msgHumidity]];

