// SIMULATOR SENSOR RUANG 1 - KELOMPOK 7

// Generate suhu antara 24-32 derajat Celsius
let temperature = Number((24 + Math.random() * 8).toFixed(1));

// Generate kelembapan antara 50-80 persen
