// Memeriksa topic suhu dari empat ruangan
const match = msg.topic.match(
    /^pens\/klp7\/(ruang[1-4])\/temperature$/
);

// Abaikan topic yang tidak sesuai
if (!match) {
    return null;
}

// Mengubah nama topic menjadi nama ruangan
const nomorRuang = match[1].replace("ruang", "");

msg.topic = "Ruang " + nomorRuang;

// Memastikan payload berupa angka
msg.payload = Number(msg.payload);

// Memberikan timestamp untuk grafik
msg.timestamp = Date.now();

return msg;
